#include <iostream>
#include <cstdio>
#include <cstring>
#include <cmath>
using namespace std;

int main()
{
    int n;
    while (scanf("%d", &n) == 1)
    {
        int a[110];
        memset(a, 0, sizeof(a));

        for (int i = 1; i <= n / 2; i++)
        {
            int x;
            scanf("%d", &x);
            if (x & 1)
                a[x] = 111;
            else
                a[x] = x;
        }

        int sum = 0, l = 1;
        for (int i = 1; i <= n; i++)
        {
            while (a[l] == 111 && l < n - 2)
                l += 2;

            if (a[i] == i)
            {
                sum += abs(i - l);
                a[l] = 111;
            }
        }

        printf("%d\n", sum);
    }

    return 0;
}

